import logo from './logo.svg';
import './App.css';
import {useState} from "react";

function App() {
    const [user, setUser] = useState('unknown');
    const handleClick = ()=>{
        fetch('/api-test')
            .then(res=> res.json())
            .then(data=>alert(data));
    }

    return (
        <div className="App">
            <h1>MAIN</h1>

            Your Name : &nbsp;
            <input type="text"  onChange={(e)=>{setUser(e.target.value)}}/>
            <table>
                <tbody>
                <tr>
                    <td>a</td>
                    <td>b</td>
                    <td>c</td>
                    <td>d</td>
                </tr>
                <tr>
                    <td>e</td>
                    <td>f</td>
                    <td>g</td>
                    <td>h</td>
                </tr>
                </tbody>
            </table>
            <br/>
            <button onClick={handleClick}>api test
            </button>
        </div>
    );
}

export default App;
